function run(){
  let c = 0;
  for (let q = 0; q <= 4; q++) for (let d = 0; d <= 10; d++) for (let n = 0; n <= 20; n++) {
    const p = 100 - 25 * q - 10 * d - 5 * n;
    if (p >= 0) c++;
  }
  return c;
}
